import re


class CentsField(fields.Field):
    """Load nonnegative integer minor units; dump canonical major-unit strings."""

    # Regex for valid money strings: digits with optional decimal point and 1-2 fractional digits
    MONEY_PATTERN = re.compile(r'^(\d+)(?:\.(\d{1,2}))?$')

    def _deserialize(self, value, attr, data, **kwargs):
        if not isinstance(value, str):
            raise ValidationError(f"Expected string, got {type(value).__name__}")

        match = self.MONEY_PATTERN.match(value)
        if not match:
            raise ValidationError(f"Invalid money format: {value}")

        integer_part = match.group(1)
        fractional_part = match.group(2) if match.group(2) else "00"

        # Pad fractional part to 2 digits
        if len(fractional_part) == 1:
            fractional_part = fractional_part + "0"
        elif len(fractional_part) == 2:
            fractional_part = fractional_part
        else:
            # Should be caught by regex, but just in case
            raise ValidationError(f"Invalid money format: {value}")

