import re


class CentsField(fields.Field):
    """Load nonnegative integer minor units; dump canonical major-unit strings."""

    DEFAULT_ERROR_MESSAGES = {
        'invalid': 'Value must be a valid nonnegative money string with 0-2 decimal places.'
    }

    def _deserialize(self, value, attr, data, **kwargs):
        if not isinstance(value, str):
            self.fail('invalid')

        # Check if the value matches the valid money pattern
        if not re.match(r'^[0-9]+(\.[0-9]{1,2})?$', value):
            self.fail('invalid')

        # Split into integer and fractional parts
        parts = value.split('.')
        if len(parts) == 1:
            # No decimal point, so it's whole dollars
            integer_part = int(parts[0])
            fractional_part = 0
        else:
            # Has decimal point
            integer_part = int(parts[0])
            fractional_part = int(parts[1])

            # Ensure fractional part doesn't have more than 2 digits
            if len(parts[1]) > 2:
                self.fail('invalid')

        # Calculate total cents
        cents = integer_part * 100 + fractional_part

        return cents

    def _serialize(self, value, attr, obj, **kwargs):
        if not isinstance(value, int):
            raise ValueError('Value must be an integer representing cents')

        if value < 0:
            raise ValueError('Value must be nonnegative')

        # Format as dollars with exactly 2 decimal places
        dollars = value / 100.0
        return f'{dollars:.2f}'


class LedgerSchema(Schema):
    id = fields.String(required=True)
    amount = CentsField(required=True)

