def ledger_report(rows):
    """Import ledger rows and report accepted, rejected and total."""
    schema = LedgerSchema()
    accepted = []
    rejected = []
    seen_ids = set()
    total_cents = 0

    for index, row in enumerate(rows):
        try:
            # Validate the row using the schema
            result = schema.load(row)

            # Check for duplicate IDs
            if result['id'] in seen_ids:
                rejected.append({'index': index, 'reason': 'duplicate'})
            else:
                # Accept the row
                accepted.append({
                    'id': result['id'],
                    'amount': schema.dump({'amount': result['amount']})['amount']
                })
                seen_ids.add(result['id'])
                total_cents += result['amount']
        except Exception as e:
            # If validation fails, reject the row
            rejected.append({'index': index, 'reason': 'invalid'})

